		this.led_bmp_removal!!.Assign_VecT(s!!.led_bmp_removal)
		this.led_wet_deposition!!.Assign_VecT(s!!.led_wet_deposition)
		this.led_infil_loss!!.Assign_VecT(s!!.led_infil_loss)
		this.led_reacted!!.Assign_VecT(s!!.led_reacted)
		this.led_reaction_clamped!!.Assign_VecT(s!!.led_reaction_clamped)
		this.led_ponded_lost!!.Assign_VecT(s!!.led_ponded_lost)
		this.led_subcatch_load!!.Assign_VecT(s!!.led_subcatch_load)
		this.resolved = s!!.resolved
	}

	open fun MoveFrom(s: MsxSurfaceData?) {
		if (this === s) {
			return
		}
		this.rows = s!!.rows
		s!!.rows = MsxSurfaceRows()
		this.n_landuses = s!!.n_landuses
		this.n_species = s!!.n_species
		this.n_subcatch = s!!.n_subcatch
		this.bu_type = s!!.bu_type
