	open fun active(): Boolean {
		return this.resolved && (this.n_species > 0)
	}

	open fun pidx(lu: Int, m: Int): Long {
		return (lu.toLong() * this.n_species.toLong()) + m.toLong()
	}

	open fun bu_idx(sc: Int, lu: Int, m: Int): Long {
		return (((sc.toLong() * this.n_landuses.toLong()) + lu.toLong()) * this.n_species.toLong()) + m.toLong()
	}

	open fun sidx(sc: Int, m: Int): Long {
		return (sc.toLong() * this.n_species.toLong()) + m.toLong()
	}

	open fun resize_params(nlu: Int, nm: Int) {
		this.n_landuses = nlu
		this.n_species = nm
		var n: Long = nlu.toLong() * nm.toLong()
		this.bu_type!!.assign_ul_T(n, 0)
		this.bu_c1!!.assign_ul_T(n, 0.0)
		this.bu_c2!!.assign_ul_T(n, 0.0)
		this.bu_c3!!.assign_ul_T(n, 0.0)
		this.bu_normalizer!!.assign_ul_T(n, 0)
		this.bu_max_days!!.assign_ul_T(n, 0.0)
		this.wo_type!!.assign_ul_T(n, 0)
		this.wo_coeff!!.assign_ul_T(n, 0.0)
		this.wo_expon!!.assign_ul_T(n, 0.0)
		this.wo_sweep_effic!!.assign_ul_T(n, 0.0)
		this.wo_bmp_effic!!.assign_ul_T(n, 0.0)
		this.mcf!!.assign_ul_T(nm.toLong(), 1.0)
		if (this.c_rain!!.size() != nm.toLong()) {
			this.c_rain!!.assign_ul_T(nm.toLong(), 0.0)
		}
		this.snow_only!!.assign_ul_T(nm.toLong(), false)
	}

	open fun resize_state(nsc: Int) {
		this.n_subcatch = nsc
		var nm: Long = this.n_species.toLong()
		this.buildup!!.assign_ul_T((nsc.toLong() * this.n_landuses.toLong()) * nm, 0.0)
		this.washoff_conc!!.assign_ul_T(nsc.toLong() * nm, 0.0)
		this.washoff_conc_old!!.assign_ul_T(nsc.toLong() * nm, 0.0)
		this.ponded_qual!!.assign_ul_T(nsc.toLong() * nm, 0.0)
		this.runon_qual_rate!!.assign_ul_T(nsc.toLong() * nm, 0.0)
		this.lid_drain_runon_load!!.assign_ul_T(nsc.toLong() * nm, 0.0)
		if (this.init_loading!!.size() != (nsc.toLong() * nm)) {
			this.init_loading!!.assign_ul_T(nsc.toLong() * nm, 0.0)
		}
		this.led_init_buildup!!.assign_ul_T(nm, 0.0)
		this.led_buildup!!.assign_ul_T(nm, 0.0)
		this.led_runoff_load!!.assign_ul_T(nm, 0.0)
		this.led_sweeping!!.assign_ul_T(nm, 0.0)
		this.led_bmp_removal!!.assign_ul_T(nm, 0.0)
		this.led_wet_deposition!!.assign_ul_T(nm, 0.0)
		this.led_infil_loss!!.assign_ul_T(nm, 0.0)
		this.led_ponded_lost!!.assign_ul_T(nm, 0.0)
		this.led_reacted!!.assign_ul_T(nm, 0.0)
		this.led_reaction_clamped!!.assign_ul_T(nm, 0.0)
		this.led_subcatch_load!!.assign_ul_T(nsc.toLong() * nm, 0.0)
	}

	companion object {
		@JvmStatic fun New_rMsxSurfaceData(p: MsxSurfaceData?): MsxSurfaceData? {
			var o: MsxSurfaceData? = MsxSurfaceData(cpp.Raw.V)
			o!!.__init_rMsxSurfaceData(p)
			return o
		}

		@JvmStatic fun New_mMsxSurfaceData(p: MsxSurfaceData?): MsxSurfaceData? {
			var o: MsxSurfaceData? = MsxSurfaceData(cpp.Raw.V)
			o!!.__init_mMsxSurfaceData(p)
			return o
		}

		@JvmStatic fun New(): MsxSurfaceData? {
			var o: MsxSurfaceData? = MsxSurfaceData(cpp.Raw.V)
			o!!.__init_d()
			return o
		}

		@JvmStatic fun MoveNew(s: MsxSurfaceData?): MsxSurfaceData? {
			var o: MsxSurfaceData? = MsxSurfaceData(cpp.Raw.V)
			o!!.MoveFrom(s)
			return o
		}

	}
